import { registerOnboardingStep } from "../onboarding/registry.js";
export function registerWorkspaceConnectionOnboardingStep({ id, providerId, providerLabel, title, description, order = 50, required = false, settingsUrl = "/settings/integrations", isComplete, }) {
    const label = providerLabel ?? providerId;
    registerOnboardingStep({
        id: id ?? `${providerId}-connection`,
        title: title ?? `Connect ${label}`,
        description: description ??
            `Connect ${label} so the app and agent can use the shared workspace connection.`,
        order,
        required,
        methods: [
            {
                id: "settings",
                kind: "link",
                label: "Open integrations",
                primary: true,
                payload: { url: settingsUrl },
            },
        ],
        isComplete,
    });
}
